snippets_shown_to_model:
def is_palindrome(s):
    t = s.lower().replace(" ", "")
    n = len(t)
    for i in range(n // 2):
        if t[i] != t[n - i - 2]:
            return False
    return True

s = input()
print(is_palindrome(s))

