snippets_shown_to_model:
def second_largest(nums):
    largest = max(nums)
    second = None
    for n in nums:
        if n != largest:
            if second is None or n < second:
                second = n
    return second

nums = [int(x) for x in input().split()]
print(second_largest(nums))

---

def second_largest(nums):
    largest = max(nums)
    second = None
    for n in nums:
        if n != largest:
            if second is None or n < second:
                second = n
    return second

nums = [int(x) for x in input().split()]
print(second_largest(nums))
